def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    letter_map = {}
    for i, letter in enumerate(encoded):
        if letter not in letter_map:
            letter_map[letter] = original[i]
        else:
            if letter_map[letter] != original[i]:
                return "Failed"

    # Use the mapping to decode the message
    decoded = ""
    for letter in message:
        if letter in letter_map:
            decoded += letter_map[letter]
        else:
            return "Failed"

    return decoded
