def count_coprime_pairs(x0, y0):
    count = 0
    for a in range(1, y0 // x0 + 1):
        if y0 % (a * x0) == 0:
            b = y0 // (a * x0)
            if a == b:
                count += 1
            elif a * b == y0 // x0:
                count += 2
    return count
